SELECT COUNT(*) AS canceled_orders_count
FROM orders
WHERE order_status = 'canceled';

SELECT COUNT(*) AS number_of_sellers
FROM sellers
WHERE seller_state = 'SP';

SELECT COUNT(*) AS review_count
FROM order_reviews
WHERE review_score = 5;

SELECT COUNT(*) AS null_product_category_count
FROM products
WHERE product_category_name IS NULL;
